# The engine. Run me after each of your moves.
LINES = [(0,1,2),(3,4,5),(6,7,8),(0,3,6),(1,4,7),(2,5,8),(0,4,8),(2,4,6)]

def winner(b):
    for a, c, d in LINES:
        if b[a] != "." and b[a] == b[c] == b[d]:
            return b[a]
    return None

nodes = 0

def minimax(b, player, alpha, beta):
    """Score from O's viewpoint: +1 win, 0 draw, -1 loss. Prefer fast wins."""
    global nodes
    nodes += 1
    w = winner(b)
    if w == "o": return 1
    if w == "x": return -1
    if "." not in b: return 0
    best = -2 if player == "o" else 2
    for i, ch in enumerate(b):
        if ch != ".":
            continue
        score = minimax(b[:i] + player + b[i+1:], "x" if player == "o" else "o", alpha, beta)
        if player == "o":
            best = max(best, score)
            alpha = max(alpha, best)
        else:
            best = min(best, score)
            beta = min(beta, best)
        if beta <= alpha:
            break          # alpha-beta cut: this branch can't matter
    return best

state = nb.get("ttt") or {"board": ".........", "turn": "human", "status": "your move"}
b = state["board"]

w = winner(b)
if w or "." not in b:
    verdict = {"x": "X wins!", "o": "O wins."}.get(w, "Draw.")
    print("game over:", verdict)
    nb["ttt"] = {"board": b, "turn": "human", "status": verdict + " Click 'new game'."}
elif state["turn"] != "engine":
    print("it's your move - click a square on the board above, then re-run me")
else:
    best_score, best_move = -2, None
    for i, ch in enumerate(b):
        if ch != ".":
            continue
        nodes = 0
        score = minimax(b[:i] + "o" + b[i+1:], "x", -2, 2)
        print(f"square {i+1}: score {score:+d}  ({nodes} nodes searched)")
        if score > best_score:
            best_score, best_move = score, i

    b = b[:best_move] + "o" + b[best_move+1:]
    w = winner(b)
    outlook = {1: "O expects to WIN", 0: "best play leads to a draw", -1: "O is losing?!"}[best_score]
    if w == "o":
        status = "O wins."
    elif "." not in b:
        status = "Draw. Click 'new game'."
    else:
        status = f"O took square {best_move+1} - {outlook}. Your move."
    print(f"\nengine plays square {best_move+1} ({outlook})")
    nb["ttt"] = {"board": b, "turn": "human", "status": status}
